def collect_bundle(results_dir: Path) -> dict:
    """Read every result file and every attachment file into one dict."""
    bundle = {"results": [], "attachments": {}}

    for result_file in sorted(results_dir.glob("*-result.json")):
        with open(result_file, "r", encoding="utf-8") as f:
            bundle["results"].append(json.load(f))

    for attachment_file in sorted(results_dir.glob("*-attachment.*")):
        raw_bytes = attachment_file.read_bytes()
        bundle["attachments"][attachment_file.name] = base64.b64encode(raw_bytes).decode("ascii")

    return bundle

@dataclass
class Attachment:
    name: str
    mime_type: str
    data: bytes


@dataclass
class Step:
    name: str
    status: str
    attachments: list = field(default_factory=list)


@dataclass
class TestCase:
    name: str
    status: str
    failure_message: Optional[str]
    failure_trace: Optional[str]
    steps: list = field(default_factory=list)

def extract_bundle_json(html_text: str) -> dict:
    """Pull the base64+gzip blob out of the <script> tag and turn it back into a dict."""
    match = re.search(
        r'<script id="report-bundle"[^>]*>([^<]+)</script>',
        html_text,
    )
    if not match:
        raise ValueError("No report-bundle script tag found in this HTML file")

    encoded_text = match.group(1)
    compressed_bytes = base64.b64decode(encoded_text)
    json_text = gzip.decompress(compressed_bytes).decode("utf-8")
    return json.loads(json_text)

def guess_mime_type(attachment_filename: str) -> str:
    extension = Path(attachment_filename).suffix.lower()
    return {
        ".png": "image/png",
        ".jpg": "image/jpeg",
        ".csv": "text/csv",
        ".html": "text/html",
        ".txt": "text/plain",
    }.get(extension, "application/octet-stream")

